#include <bits/stdc++.h>
using namespace std;

int n = 6, cnt = 0;
int col[20];
bool usedC[20], d1[40], d2[40];
vector<int> firstSol;

void dfs(int r) {
    if (r == n) {
        cnt++;
        if (firstSol.empty()) firstSol.assign(col, col + n);
        return;
    }
    for (int c = 0; c < n; c++) {
        if (usedC[c] || d1[r + c] || d2[r - c + n]) continue;
        usedC[c] = d1[r + c] = d2[r - c + n] = true;
        col[r] = c;
        dfs(r + 1);
        usedC[c] = d1[r + c] = d2[r - c + n] = false;
    }
}

int target = 10;
vector<int> nums = {2, 3, 5, 7, 8};
vector<vector<int>> ans;

void comb(int idx, int sum, vector<int>& cur) {
    if (sum == target) { ans.push_back(cur); return; }
    if (sum > target || idx == (int)nums.size()) return;
    cur.push_back(nums[idx]);
    comb(idx, sum + nums[idx], cur);
    cur.pop_back();
    comb(idx + 1, sum, cur);
}

int main() {
    dfs(0);
    cout << "queens " << n << ": " << cnt << "\n";
    for (int r = 0; r < n; r++) {
        for (int c = 0; c < n; c++) cout << (firstSol[r] == c ? 'Q' : '.');
        cout << "\n";
    }
    vector<int> cur;
    comb(0, 0, cur);
    cout << ans.size() << " combos\n";
    for (auto& v : ans) {
        for (size_t i = 0; i < v.size(); i++) cout << v[i] << (i + 1 < v.size() ? "+" : "\n");
    }
    return 0;
}

