#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll, int> pli;
#define F first
#define S second
const ll INF = 1e18;
const int N = 8;
vector<pair<int, int>> g[N];
ll dist[N];
int par[N];

void addEdge(int u, int v, int w) {
    g[u].push_back({v, w});
    g[v].push_back({u, w});
}

int main() {
    int edges[][3] = {{0, 1, 4}, {0, 2, 1}, {2, 1, 2}, {1, 3, 5}, {2, 3, 8},
                      {3, 4, 3}, {4, 5, 1}, {3, 5, 6}, {5, 6, 2}};
    for (auto& e : edges) addEdge(e[0], e[1], e[2]);
    fill(dist, dist + N, INF);
    memset(par, -1, sizeof(par));
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    dist[0] = 0;
    pq.push({0, 0});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto& e : g[u]) {
            if (dist[u] + e.S < dist[e.F]) {
                dist[e.F] = dist[u] + e.S;
                par[e.F] = u;
                pq.push({dist[e.F], e.F});
            }
        }
    }
    for (int i = 0; i < N; i++) {
        cout << i << ": ";
        if (dist[i] == INF) { cout << "unreachable\n"; continue; }
        vector<int> path;
        for (int v = i; v != -1; v = par[v]) path.push_back(v);
        reverse(path.begin(), path.end());
        cout << dist[i] << " via ";
        for (int k = 0; k < (int)path.size(); k++) cout << path[k] << (k + 1 == (int)path.size() ? "" : "->");
        cout << "\n";
    }
    return 0;
}

