vector<string> split(const string& s, char delim) {
    vector<string> res;
    size_t start = 0, pos;
    while ((pos = s.find(delim, start)) != string::npos) {
        if (pos > start) res.push_back(s.substr(start, pos - start));
        start = pos + 1;
    }
    if (start < s.size()) res.push_back(s.substr(start));
    return res;
}

string normalize(string w) {
    string r;
    for (char c : w) {
        if (c >= 'A' && c <= 'Z') r += char(c - 'A' + 'a');
        else if (c >= 'a' && c <= 'z') r += c;
    }
    return r;
}

int main() {
