#include <bits/stdc++.h>
using namespace std;
const int R = 6, C = 8;
string grid[R] = {
    "S..#....",
    ".#.#.##.",
    ".#...#..",
    ".####.#.",
    "......#E",
    "##.#...."};
int dist_[R][C];
int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
char dname[] = "UDLR";
char how[R][C];

int main() {
    memset(dist_, -1, sizeof(dist_));
    queue<pair<int, int>> q;
    int sr = 0, sc = 0, er = -1, ec = -1;
    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++)
            if (grid[i][j] == 'S') sr = i, sc = j;
            else if (grid[i][j] == 'E') er = i, ec = j;
    dist_[sr][sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            if (grid[nr][nc] == '#' || dist_[nr][nc] != -1) continue;
            dist_[nr][nc] = dist_[r][c] + 1;
            how[nr][nc] = dname[k];
            q.push({nr, nc});
        }
    }
    cout << "steps: " << dist_[er][ec] << "\n";
    string path;
    for (int r = er, c = ec; r != sr || c != sc;) {
        char d = how[r][c];
        path += d;
        int k = strchr(dname, d) - dname;
        r -= dr[k], c -= dc[k];
    }
    reverse(path.begin(), path.end());
    cout << path << "\n";
    int reach = 0;
    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            if (dist_[i][j] >= 0) reach++;
            cout << (grid[i][j] == '#' ? '#' : dist_[i][j] < 0 ? '?' : char('0' + dist_[i][j] % 10));
        }
        cout << "\n";
    }
    cout << "reachable=" << reach << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

string s;
int pos;

ll expr();
ll factor() {
    if (s[pos] == '(') {
        pos++;
        ll v = expr();
        pos++;
        return v;
    }
    if (s[pos] == '-') { pos++; return -factor(); }
    ll v = 0;
    while (pos < (int)s.size() && isdigit(s[pos])) v = v * 10 + (s[pos++] - '0');
    return v;
}
ll term() {
    ll v = factor();
    while (pos < (int)s.size() && (s[pos] == '*' || s[pos] == '/' || s[pos] == '%')) {
        char op = s[pos++];
        ll r = factor();
        v = op == '*' ? v * r : op == '/' ? v / r : v % r;
    }
    return v;
}
ll expr() {
    ll v = term();
    while (pos < (int)s.size() && (s[pos] == '+' || s[pos] == '-')) {
        char op = s[pos++];
        ll r = term();
        if (op == '+') v += r; else v -= r;
    }
    return v;
}

bool balanced(const string& t) {
    stack<char> st;
    for (char c : t) {
        if (c == '(' || c == '[' || c == '{') st.push(c);
        else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char o = st.top(); st.pop();
            if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{')) return false;
        }
    }
    return st.empty();
}

int main() {
    vector<string> es = {"1+2*3", "(1+2)*3", "100/(4-1)%7", "-(3+4)*-2", "2*(3+(4-1)*5)-10"};
